package com.bocsoft.sqleditor.history;
import com.bocsoft.sqleditor.auth.CurrentAuth;import com.bocsoft.sqleditor.datasource.api.CursorPage;import com.bocsoft.sqleditor.history.api.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/sql/history") public class HistoryController {private final HistoryQueryService service;public HistoryController(HistoryQueryService service){this.service=service;}@GetMapping public CursorPage<HistorySummary>list(@RequestParam(defaultValue="")String keyword,@RequestParam(required=false)String dataSourceId,@RequestParam(required=false)String database,@RequestParam(required=false)String status,@RequestParam(required=false)String statementType,@RequestParam(defaultValue="30")int pageSize,@RequestParam(required=false)String pageToken){return service.list(CurrentAuth.get(),keyword,dataSourceId,database,status,statementType,pageSize,pageToken);}@GetMapping("/{id}")public HistoryDetail detail(@PathVariable String id){return service.detail(CurrentAuth.get(),id);}}
